export interface CancelScheduledArgs {
  sender: string;
  intentId: U64;
}

/**
 * Reclaims a pending intent that passed `expires_at` without being fully
 * executed, refunding the sender the escrow for every outstanding
 * occurrence.
 * **Permissionless**: anyone may trigger the refund (the funds always go
 * to the sender), so abandoned intents cannot lock capital indefinitely.
 * Reverts with [`StreamError::IntentExpired`]-style semantics via
 * [`StreamError::IntentNotExpired`] if called too early, and with
 * [`StreamError::IntentNotPending`] if the intent is terminal.
 */
export interface ReclaimExpiredArgs {
  intentId: U64;
}

/**
 * Read-only view of a scheduled intent's full state.
 */
export interface GetIntentArgs {
  intentId: U64;
}

/**
 * A page of scheduled-intent ids created by `sender`, in creation order.
 * Same pagination and advisory semantics as
 * [`StreamingPayments::sender_streams`].
 */
export interface SenderIntentsArgs {
  sender: string;
  offset: U32;
  limit: U32;
}

/**
 * Sets the protocol fee rate (basis points on each new stream's
 * deposit, charged once at creation). Governor-only. Reverts with
 * [`StreamError::FeeRateTooHigh`] above [`MAX_FEE_BPS`] (the protocol
 * cap) and with [`StreamError::NotGovernor`] for any other caller.
 * Changes apply only to streams created afterwards: fees are a
 * property of the deposit boundary a stream actually crossed, never
 * retroactively.
 */
export interface SetFeeBpsArgs {
  caller: string;
  newFeeBps: U32;
}

/**
 * Nominates `new_governor` as the next treasury governor (governor-only,
 * step 1 of a two-step rotation). Two steps mean a typo'd address can
 * never irreversibly strand the treasury: only an address that can
 * prove control (`accept_governor`) ever becomes governor.
 */
export interface NominateGovernorArgs {
  caller: string;
  newGovernor: string;
}

/**
 * Completes a governor rotation (step 2): the nominated address proves
 * control by authorizing this call and becomes the governor. Reverts
 * with [`StreamError::NoPendingGovernor`] when nothing is pending and
 * [`StreamError::NotGovernor`] for a caller who is not the nominee.
 */
export interface AcceptGovernorArgs {
  caller: string;
}

/**
 * Withdraws accumulated protocol fees for `token` to `recipient`.
 * Governor-only; bounded by fees collected minus fees already
 * withdrawn ([`StreamError::InsufficientTreasuryBalance`]).
 * Effects-interactions ordered: `FeeWithdrawn` is emitted and the
 * accounting persisted *before* the token transfer. A token-side failure
 * to pay out returns [`StreamError::TreasuryPayoutFailed`], rolling the
 * recorded withdrawal and the event back with it.
 */
export interface WithdrawTreasuryArgs {
  caller: string;
  token: string;
  recipient: string;
  amount: Int128;
}

/**
 * One-call treasury snapshot for `token`: governor, pending nominee,
 * current fee configuration, and the fee ledger totals that must
 * reconcile with the `FeeCharged` / `FeeWithdrawn` event streams.
 * Public, read-only, no auth.
 */
export interface TreasuryStatusArgs {
  token: string;
}

/**
 * The protocol fee charged for `stream_id` at creation, in smallest
 * token units. Zero for streams created while fees were disabled (or
 * whose fee rounded to zero). Reverts with
 * [`StreamError::StreamNotFound`] for unknown ids.
 */
export interface StreamFeeArgs {
  streamId: U64;
}

/**
 * One bounded page of the fee verification scan: sums stored
 * per-stream fees for `token` over a window of the stream-id space
 * (`count` clamped to [`MAX_PAGE_SIZE`]). Page from id 1 until `done`
 * is true; the summed `fees_in_range` values must equal
 * `treasury_status(token).charged_total` — and both must equal the
 * amounts in the contract's `FeeCharged` events. That three-way
 * equality is the treasury invariant, verifiable by anyone from
 * public reads alone (see `scripts/verify-fees.ts`).
 */
export interface VerifyTreasuryArgs {
  token: string;
  startId: U64;
  count: U32;
}

/**
 * Registers (or reconfigures) a sponsor budget and its authorized operator
 * (relayer) key. See [`sponsor`].
 */
export interface RegisterSponsorArgs {
  sponsor: string;
  token: string;
  perPeriodLimit: Int128;
  perBeneficiaryLimit: Int128;
  windowSeconds: U64;
  operatorKey: Bytes;
}

/**
 * Pauses or resumes a sponsor's budget.
 */
export interface SetSponsorActiveArgs {
  sponsor: string;
  active: boolean;
}

/**
 * Rotates a sponsor's authorized operator (relayer) key.
 */
export interface RotateOperatorKeyArgs {
  sponsor: string;
  newOperatorKey: Bytes;
}

/**
 * Binds (or rotates) a beneficiary's ed25519 consent key.
 */
export interface EnrollBeneficiaryArgs {
  beneficiary: string;
  publicKey: Bytes;
}

/**
 * Relays a beneficiary's withdrawal with a sponsor absorbing the gas. See
 * [`sponsor`] for the inner-authorization and budget semantics.
 */
export interface SponsoredWithdrawArgs {
  sponsor: string;
  beneficiary: string;
  streamId: U64;
  amount: Int128;
  nonce: U64;
  deadline: U64;
  operatorSig: Bytes;
  beneficiarySig: Bytes;
}

/**
 * Reads a sponsor's budget configuration, if any.
 */
export interface GetSponsorArgs {
  sponsor: string;
}

/**
 * Reads a beneficiary's enrolled consent key, if any.
 */
export interface GetBeneficiaryPublicKeyArgs {
  beneficiary: string;
}

/**
 * The sponsor's current-window spend.
 */
export interface SponsorPeriodSpendArgs {
  sponsor: string;
}

/**
 * A beneficiary's spend within a sponsor's current window.
 */
export interface BeneficiarySpendArgs {
  sponsor: string;
  beneficiary: string;
}

/**
 * Initializes the policy module with `admin`. Callable once only; panics
 * if called again. Admin authorization is required.
 */
export interface PolicyInitArgs {
  admin: string;
}

/**
 * Queues an allowlist mutation (adding or removing `asset`) with a
 * timelock delay. Callable only by the current admin.
 */
export interface PolicyProposeAssetArgs {
  asset: string;
  allowed: boolean;
}

/**
 * Executes a queued asset allowlist change after the timelock has elapsed.
 * Callable by anyone: once a change has been vetted by the admin and the
 * public timelock delay has expired, execution is permissionless so it
 * cannot be stalled or held hostage by an absent admin.
 */
export interface PolicyExecuteAssetArgs {
  asset: string;
}

/**
 * Proposes a new admin for the two-step handoff (admin-only).
 */
export interface PolicyProposeHandoffArgs {
  newAdmin: string;
}

/**
 * Sets the timelock delay in seconds (admin-only).
 */
export interface PolicySetTimelockDelayArgs {
  delay: U64;
}

/**
 * Read-only check whether `asset` is currently allowed for new streams.
 */
export interface PolicyIsAssetAllowedArgs {
  asset: string;
}

/**
 * Returns the queued allowlist change for `asset`, if any.
 */
export interface PolicyGetQueuedAssetArgs {
  asset: string;
}

/**
 * Sets governance policy floors and ceilings for streams of `token`, or global default if `token` is None.
 * Governor-only.
 * Governance timelock hook: this setter gates via `treasury::require_governor` and will route
 * through the timelocked proposal queue once governance timelocks are enabled across all operations.
 */
export interface SetStreamPolicyArgs {
  caller: string;
  token: string | null;
  policy: StreamPolicy;
}

/**
 * Queries the effective stream policy for `token` (falling back to global policy if unset).
 */
export interface GetStreamPolicyArgs {
  token: string | null;
}

/**
 * Sets the freeze state of the contract. Governor-only.
 * When frozen, mutating stream entrypoints (create, withdraw, withdraw_max,
 * cancel, top_up) revert with [`StreamError::ContractFrozen`], but read views
 * remain accessible.
 */
export interface SetFrozenArgs {
  caller: string;
  frozen: boolean;
}

/**
 * Proposes a Wasm bytecode upgrade with an enforced timelock delay. Governor-only.
 * `delay_seconds` must be at least [`MIN_UPGRADE_DELAY_SECONDS`] (24 hours).
 * Overwrites any existing proposal.
 */
export interface ProposeUpgradeArgs {
  caller: string;
  newWasmHash: Bytes;
  delaySeconds: U64;
}

/**
 * Cancels a pending upgrade proposal. Governor-only.
 * Reverts with [`StreamError::NoPendingUpgrade`] if no proposal is pending.
 */
export interface CancelUpgradeArgs {
  caller: string;
}

/**
 * Executes a pending upgrade proposal once its timelock delay has elapsed. Governor-only.
 * Updates the contract executable via [`env.deployer().update_current_contract_wasm`]
 * and clears the pending upgrade.
 */
export interface ExecuteUpgradeArgs {
  caller: string;
}

/**
 * Migrates a batch of streams from schema v1 to schema v2. Governor-only.
 * Requires the contract to be frozen ([`StreamError::ContractNotFrozen`]).
 * `count` is clamped to [`MAX_MIGRATION_BATCH_SIZE`] (50 streams per call).
 * If `start_id == 0`, migration resumes from `migration_cursor + 1`.
 * When the cursor reaches `total_streams`, the schema version is bumped to v2.
 * Calling this after migration is complete reverts with [`StreamError::AlreadyMigrated`].
 */
export interface MigrateStorageArgs {
  caller: string;
  startId: U64;
  count: U32;
}

/**
 * Configures the oracle publisher set, threshold, and staleness bound.
 * Authorized by the treasury governor.
 */
export interface SetOracleConfigArgs {
  caller: string;
  publishers: string[];
  threshold: U32;
  maxStaleSeconds: U64;
}

/**
 * Records an authorized external time feed report.
 */
export interface SubmitOracleTimeArgs {
  publisher: string;
  timestamp: U64;
}

/**
 * Resolves reference timestamp for a given stream id and oracle flag.
 */
export interface ResolveTimeArgs {
  streamId: U64;
  useOracle: boolean;
}

/**
 * Reads latest report from a publisher.
 */
export interface OracleReportArgs {
  publisher: string;
}

// --------------------------------------------------------------------- //
// Runtime helpers                                                        //
// --------------------------------------------------------------------- //

function asNative(value: xdr.ScVal): unknown {
  return scValToNative(value) as unknown;
}

function asBigInt(value: unknown, label: string): bigint {
  if (typeof value === "bigint") return value;
  if (typeof value === "number" && Number.isInteger(value)) return BigInt(value);
  if (typeof value === "string" && /^-?\d+$/.test(value)) return BigInt(value);
  throw new Error(`${label}: expected an integer, got ${typeof value}`);
}

function asNumber(value: unknown, label: string): number {
  if (typeof value === "number" && Number.isInteger(value)) return value;
  if (typeof value === "bigint") return Number(value);
  throw new Error(`${label}: expected a number, got ${typeof value}`);
}

function asString(value: unknown, label: string): string {
  if (typeof value !== "string") throw new Error(`${label}: expected a string`);
  return value;
}

function asBool(value: unknown, label: string): boolean {
  if (typeof value !== "boolean") throw new Error(`${label}: expected a bool`);
  return value;
}

function asBytes(value: unknown, label: string, length: number): Uint8Array {
  if (!(value instanceof Uint8Array)) throw new Error(`${label}: expected bytes`);
  if (value.length !== length) {
    throw new Error(`${label}: expected ${length} bytes, got ${value.length}`);
  }
  return value;
}

function asArray(value: unknown, label: string): unknown[] {
  if (!Array.isArray(value)) throw new Error(`${label}: expected an array`);
  return value;
}

export function addressToScVal(value: string): xdr.ScVal {
  return nativeToScVal(new Address(value), { type: "address" });
}

function structScVal(entries: Array<[string, xdr.ScVal]>): xdr.ScVal {
  const sorted = [...entries].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return xdr.ScVal.scvMap(
    sorted.map(([key, val]) => new xdr.ScMapEntry({ key: xdr.ScVal.scvSymbol(key), val }))
  );
}

export function encodeOwnershipRole(value: OwnershipRole): xdr.ScVal {
  switch (value) {
    case "Sender":
      return nativeToScVal(0, { type: "u32" });
    case "Recipient":
      return nativeToScVal(1, { type: "u32" });
    default:
      throw new Error(`invalid OwnershipRole: ${String(value)}`);
  }
}

export function decodeOwnershipRole(value: unknown): OwnershipRole {
  switch (Number(value)) {
    case 0:
      return "Sender";
    case 1:
      return "Recipient";
    default:
      throw new Error(`unknown OwnershipRole: ${String(value)}`);
  }
}

export function encodeStreamStatus(value: StreamStatus): xdr.ScVal {
  switch (value) {
    case "Active":
      return nativeToScVal(0, { type: "u32" });
    case "Cancelled":
      return nativeToScVal(1, { type: "u32" });
    case "Depleted":
      return nativeToScVal(2, { type: "u32" });
    default:
      throw new Error(`invalid StreamStatus: ${String(value)}`);
  }
}

export function decodeStreamStatus(value: unknown): StreamStatus {
  switch (Number(value)) {
    case 0:
      return "Active";
    case 1:
      return "Cancelled";
    case 2:
      return "Depleted";
    default:
      throw new Error(`unknown StreamStatus: ${String(value)}`);
  }
}

export function encodeIntentStatus(value: IntentStatus): xdr.ScVal {
  switch (value) {
    case "Pending":
      return nativeToScVal(0, { type: "u32" });
    case "Executed":
      return nativeToScVal(1, { type: "u32" });
    case "Cancelled":
      return nativeToScVal(2, { type: "u32" });
    case "Expired":
      return nativeToScVal(3, { type: "u32" });
    default:
      throw new Error(`invalid IntentStatus: ${String(value)}`);
  }
}

export function decodeIntentStatus(value: unknown): IntentStatus {
  switch (Number(value)) {
    case 0:
      return "Pending";
    case 1:
      return "Executed";
    case 2:
      return "Cancelled";
    case 3:
      return "Expired";
    default:
      throw new Error(`unknown IntentStatus: ${String(value)}`);
  }
}

export function encodeStreamInput(value: StreamInput): xdr.ScVal {
  return structScVal([
    ["recipient", addressToScVal(value.recipient)],
    ["token", addressToScVal(value.token)],
    ["deposit_amount", nativeToScVal(asBigInt(value.depositAmount, "StreamInput.deposit_amount"), { type: "i128" })],
    ["start_time", nativeToScVal(asBigInt(value.startTime, "StreamInput.start_time"), { type: "u64" })],
    ["end_time", nativeToScVal(asBigInt(value.endTime, "StreamInput.end_time"), { type: "u64" })],
    ["cancelable", nativeToScVal(value.cancelable)],
  ]);
}

export function decodeStreamInput(value: unknown): StreamInput {
  if (value === null || typeof value !== "object") {
    throw new Error("decodeStreamInput: expected a map");
  }
  const native = value as Record<string, unknown>;
  return {
    recipient: asString(native.recipient, "StreamInput.recipient"),
    token: asString(native.token, "StreamInput.token"),
    depositAmount: asBigInt(native.deposit_amount, "StreamInput.deposit_amount"),
    startTime: asBigInt(native.start_time, "StreamInput.start_time"),
    endTime: asBigInt(native.end_time, "StreamInput.end_time"),
    cancelable: asBool(native.cancelable, "StreamInput.cancelable"),
  };
}

export function encodePendingOwnership(value: PendingOwnership): xdr.ScVal {
  return structScVal([
    ["stream_id", nativeToScVal(asBigInt(value.streamId, "PendingOwnership.stream_id"), { type: "u64" })],
    ["proposed_by", addressToScVal(value.proposedBy)],
    ["new_owner", addressToScVal(value.newOwner)],
    ["role", encodeOwnershipRole(value.role)],
    ["expires_at", nativeToScVal(asBigInt(value.expiresAt, "PendingOwnership.expires_at"), { type: "u64" })],
  ]);
}

